def minAdjacentSwaps(nums, a, b):
    MOD = 10**9 + 7
    # Classify each element: 0 if < a, 1 if in [a, b], 2 if > b
    # seen[t] = how many earlier elements have type t
    seen = [0, 0, 0]
    swaps = 0
    for v in nums:
        if v < a:
            t = 0
        elif v <= b:
            t = 1
        else:
            t = 2
        # Every earlier element with a larger type must be swapped past this one
        for bigger in range(t + 1, 3):
            swaps += seen[bigger]
        seen[t] += 1
    return swaps % MOD
